[CmdletBinding()]
param([Parameter(Mandatory=$true)][ValidatePattern('^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$')][string]$RunId)
$ErrorActionPreference='Stop';$source=Join-Path $PSScriptRoot 'Fixtures\GridBubbleVisibilityEmpty.rvt';$runs=Join-Path $PSScriptRoot 'TestRuns';$run=Join-Path $runs ('grid-bubble-'+$RunId);$model=Join-Path $run 'model.rvt';$sidecar=$model+'.fixture.json';$prefix=[IO.Path]::GetFullPath($runs).TrimEnd('\')+'\';if(![IO.Path]::GetFullPath($run).StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw 'Run path escaped QA TestRuns.'};if(!(Test-Path -LiteralPath $source -PathType Leaf)){throw 'Approved Grid Bubble fixture is missing.'};if(Test-Path -LiteralPath $run){throw 'Run directory already exists.'};New-Item -ItemType Directory -Path $run|Out-Null;Copy-Item $source $model;$hash=(Get-FileHash $source -Algorithm SHA256).Hash;@{fixtureId='GridBubbleVisibilityEmpty';sourceSha256=$hash;requiredGridNames=@('A','B','C','D','1','2','3','4')}|ConvertTo-Json|Set-Content $sidecar -Encoding UTF8;[pscustomobject]@{RunId=$RunId;ModelPath=$model;SidecarPath=$sidecar;FixtureId='GridBubbleVisibilityEmpty';SourceSha256=$hash}|ConvertTo-Json -Compress
